package com.nextaicommerce.platform.catalog;
import java.util.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class CatalogEntryDefaultsTest {
 @Test void absentOrForeignVendorCannotReadDefaultsOrWriteAnItem(){var jdbc=mock(JdbcTemplate.class);var repo=new CatalogRepository(jdbc);when(jdbc.query(anyString(),org.mockito.ArgumentMatchers.<RowMapper<String[]>>any(),any(Object[].class))).thenReturn(List.of());assertThatThrownBy(()->repo.entryDefaults(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID())).hasMessageContaining("this account");verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @Test void supplierCodeDefaultsRequireOwnSourceAndExactVendorBranchWithoutForeignPrices(){var jdbc=mock(JdbcTemplate.class);var repo=new CatalogRepository(jdbc);UUID tenant=UUID.randomUUID(),global=UUID.randomUUID(),vendor=UUID.randomUUID();when(jdbc.query(contains("SELECT coalesce(vendor_code,name)"),org.mockito.ArgumentMatchers.<RowMapper<String[]>>any(),any(Object[].class))).thenReturn(Collections.singletonList(new String[]{"KEHE","41","USD"}));when(jdbc.query(contains("FROM vendor_catalog_offers o"),org.mockito.ArgumentMatchers.<RowMapper<CatalogRepository.EntryDefaults>>any(),any(Object[].class))).thenReturn(List.of());when(jdbc.query(contains("FROM global_product_vendor_codes"),org.mockito.ArgumentMatchers.<RowMapper<String>>any(),any(Object[].class))).thenReturn(List.of("339807"));var defaults=repo.entryDefaults(tenant,global,vendor);assertThat(defaults.vendorItemCode()).isEqualTo("339807");assertThat(defaults.unitCost()).isNull();verify(jdbc).query(contains("source_tenant_id=?"),org.mockito.ArgumentMatchers.<RowMapper<String>>any(),eq(global),eq("KEHE"),eq("DC:41"),eq(tenant));verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @Test void conflictingSupplierCodesRemainBlank(){var jdbc=mock(JdbcTemplate.class);var repo=new CatalogRepository(jdbc);when(jdbc.query(contains("SELECT coalesce(vendor_code,name)"),org.mockito.ArgumentMatchers.<RowMapper<String[]>>any(),any(Object[].class))).thenReturn(Collections.singletonList(new String[]{"KEHE","41","USD"}));when(jdbc.query(contains("FROM vendor_catalog_offers o"),org.mockito.ArgumentMatchers.<RowMapper<CatalogRepository.EntryDefaults>>any(),any(Object[].class))).thenReturn(List.of());when(jdbc.query(contains("FROM global_product_vendor_codes"),org.mockito.ArgumentMatchers.<RowMapper<String>>any(),any(Object[].class))).thenReturn(List.of("339807","999999"));assertThat(repo.entryDefaults(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID()).vendorItemCode()).isNull();}
 @Test void explicitVendorSaveUsesOnlyOwnValidatedVendorAndExistingHistoryWriter(){var jdbc=mock(JdbcTemplate.class);var repo=spy(new CatalogRepository(jdbc));UUID tenant=UUID.randomUUID(),item=UUID.randomUUID(),vendor=UUID.randomUUID();doNothing().when(repo).updateAccountProduct(any(),any(),any(),any(),any());doNothing().when(repo).saveVendorOffer(any(),any(),any(),any(),any(),any(),any(),any(),any(),any());when(jdbc.query(contains("SELECT currency FROM vendors"),org.mockito.ArgumentMatchers.<ResultSetExtractor<String>>any(),any(Object[].class))).thenReturn("USD");when(jdbc.queryForList(anyString(),any(Object[].class))).thenReturn(List.of());repo.updateAccountProductVendor(tenant,item,"Own name","INTERNAL","ACTIVE",new BigDecimal("4.25"),vendor,"339807","actor");verify(repo).saveVendorOffer(tenant,"actor",item,vendor,"339807",new BigDecimal("4.25"),BigDecimal.ZERO,"USD","MANUAL","Account product editor");verify(jdbc).update(contains("preferred_vendor_id=?"),eq(vendor),eq(tenant),eq(item));}
 @Test void invalidVendorFailsBeforeAccountFieldsOrCostsChange(){var jdbc=mock(JdbcTemplate.class);var repo=spy(new CatalogRepository(jdbc));doNothing().when(repo).updateAccountProduct(any(),any(),any(),any(),any());assertThatThrownBy(()->repo.updateAccountProductVendor(UUID.randomUUID(),UUID.randomUUID(),"N","C","ACTIVE",BigDecimal.ONE,UUID.randomUUID(),"code","actor")).hasMessageContaining("this account");verify(repo,never()).updateAccountProduct(any(),any(),any(),any(),any());verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @Test void unchangedPreferredVendorCodeAndCostDoNotCreateNewHistory(){var jdbc=mock(JdbcTemplate.class);var repo=spy(new CatalogRepository(jdbc));UUID tenant=UUID.randomUUID(),item=UUID.randomUUID(),vendor=UUID.randomUUID();doNothing().when(repo).updateAccountProduct(any(),any(),any(),any(),any());when(jdbc.query(contains("SELECT currency FROM vendors"),org.mockito.ArgumentMatchers.<ResultSetExtractor<String>>any(),any(Object[].class))).thenReturn("USD");when(jdbc.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(Map.of("preferred_vendor_id",vendor,"vendor_item_code","339807","currency","USD","cost",new BigDecimal("4.25"))));repo.updateAccountProductVendor(tenant,item,"N","C","ACTIVE",new BigDecimal("4.25"),vendor,"339807","actor");verify(repo,never()).saveVendorOffer(any(),any(),any(),any(),any(),any(),any(),any(),any(),any());}

 @Test void defaultedInternalCodeCannotSilentlyDuplicateAnotherAccountProduct(){var jdbc=mock(JdbcTemplate.class);var repo=spy(new CatalogRepository(jdbc));doNothing().when(repo).updateAccountProduct(any(),any(),any(),any(),any());when(jdbc.query(contains("SELECT currency FROM vendors"),org.mockito.ArgumentMatchers.<ResultSetExtractor<String>>any(),any(Object[].class))).thenReturn("USD");when(jdbc.queryForObject(contains("id<>?"),eq(Boolean.class),any(Object[].class))).thenReturn(true);assertThatThrownBy(()->repo.updateAccountProductVendor(UUID.randomUUID(),UUID.randomUUID(),"N","DUPLICATE","ACTIVE",BigDecimal.ONE,UUID.randomUUID(),"code","actor")).hasMessageContaining("already assigned");verify(repo,never()).updateAccountProduct(any(),any(),any(),any(),any());verify(jdbc,never()).update(anyString(),any(Object[].class));}

}
